import { useState, useEffect } from 'react';
import { useAuth } from '../hooks/useAuth';
import { api } from '../services/api';
import { Loader2, Link, Copy } from 'lucide-react';
import { useToast } from '../context/ToastContext';

export default function BridgeConnectPage() {
  const { user } = useAuth();
  const { showToast } = useToast();
  const [code, setCode] = useState(null);
  const [loading, setLoading] = useState(false);
  const [students, setStudents] = useState([]);

  useEffect(() => {
    if (user?.role === 'parent') {
      api.getBridgeParentChild().then(setStudents).catch(console.error);
    } else if (user?.role === 'teacher') {
      api.getBridgeTeacherStudents().then(setStudents).catch(console.error);
    }
  }, [user]);

  const generateCode = async () => {
    setLoading(true);
    try {
      const res = await api.generateConnectionCode();
      setCode(res.code);
      showToast('Code generated! Share with your student.');
    } catch (err) {
      showToast(err.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  const copyCode = () => {
    navigator.clipboard.writeText(code);
    showToast('Copied to clipboard');
  };

  const linkStudent = async (enteredCode) => {
    try {
      await api.linkStudent(enteredCode);
      showToast('Student linked!');
      // refresh list
      if (user?.role === 'parent') {
        const data = await api.getBridgeParentChild();
        setStudents(data ? [data] : []);
      } else {
        const data = await api.getBridgeTeacherStudents();
        setStudents(data);
      }
    } catch (err) {
      showToast(err.message, 'error');
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-3xl font-bold mb-6">Bridge – Connect with Students</h1>
      
      {/* Student code generation (for students) */}
      {user?.role === 'student' && (
        <div className="card p-4 mb-6">
          <h2 className="text-xl font-semibold mb-2">Your Connection Code</h2>
          {code ? (
            <div className="flex items-center gap-3">
              <code className="bg-white/10 px-3 py-2 rounded-lg text-xl tracking-wider">{code}</code>
              <button onClick={copyCode} className="btn-secondary"><Copy size={16} /></button>
            </div>
          ) : (
            <button onClick={generateCode} disabled={loading} className="btn-primary">
              {loading ? <Loader2 size={16} className="animate-spin" /> : 'Generate Code'}
            </button>
          )}
          <p className="text-white/40 text-sm mt-2">Share this code with your parent or teacher to connect.</p>
        </div>
      )}
      
      {/* Link a student (for parents/teachers) */}
      {(user?.role === 'parent' || user?.role === 'teacher') && (
        <div className="card p-4 mb-6">
          <h2 className="text-xl font-semibold mb-2">Link a Student</h2>
          <div className="flex gap-2">
            <input
              type="text"
              id="linkCode"
              className="input flex-1"
              placeholder="Enter student's 8-digit code"
            />
            <button
              onClick={() => {
                const codeInput = document.getElementById('linkCode').value;
                if (codeInput) linkStudent(codeInput);
              }}
              className="btn-primary"
            >
              <Link size={16} className="mr-1" /> Link
            </button>
          </div>
        </div>
      )}
      
      {/* List of linked students */}
      {(user?.role === 'parent' || user?.role === 'teacher') && (
        <div className="card p-4">
          <h2 className="text-xl font-semibold mb-3">Your Linked Students</h2>
          {students.length === 0 ? (
            <p className="text-white/40">No students linked yet.</p>
          ) : (
            <div className="space-y-2">
              {students.map(s => (
                <div key={s.id} className="flex justify-between items-center p-2 bg-white/5 rounded-lg">
                  <div>
                    <p className="font-semibold">{s.full_name}</p>
                    <p className="text-sm text-white/40">Level {s.level} • {s.xp} XP</p>
                  </div>
                  <button
                    onClick={async () => {
                      const prog = await api.getBridgeStudentProgressById(s.id);
                      alert(`XP: ${prog.xp}, Level: ${prog.level}, Tasks: ${prog.tasks}, Challenges: ${prog.challenges}`);
                    }}
                    className="btn-secondary text-sm"
                  >
                    View Progress
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}